<body>
<header class="header">
  <div class="header-inner">
    <div class="brand">Booking.com</div>
    <div class="top-actions">
      <span class="currency">USD</span>
      <img class="flag-top" src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.png" width="26" height="26" alt="US">
      <span class="help btn">?</span>
      <button class="top-btn btn">Register</button>
      <button class="top-btn btn">Sign in</button>
    </div>
    <nav class="nav">
      <div class="nav-item btn"><span class="nav-icon">▱</span>Stays</div>
      <div class="nav-item btn"><span class="nav-icon">✈</span>Flights</div>
      <div class="nav-item btn"><span class="nav-icon">♧</span>Flight + Hotel</div>
      <div class="nav-item btn"><span class="nav-icon">▱</span>Car rental</div>
      <div class="nav-item btn"><span class="nav-icon">♙</span>Cruises</div>
      <div class="nav-item active btn"><span class="nav-icon">♧</span>Activities</div>
      <div class="nav-item btn"><span class="taxi-icon">TAXI</span>Airport taxis</div>
    </nav>
  </div>
</header>

<main class="page">
  <div class="back btn"><span class="back-arrow">‹</span><span>Ticket options</span></div>
  <div class="columns">
    <section class="main">
      <div class="step">Step 1 of 2</div>
      <h1>General Admission to Universal Studios Hollywood</h1>
      <div class="warning"><span class="warning-icon">!</span>Your selected date is unavailable – choose another</div>
      <div class="host">This experience is hosted by a <a href="#" class="btn">business</a></div>

      <h2 class="section-title">Your details</h2>
      <div class="signin btn"><span class="user-icon"></span>Sign in to use your saved details</div>

      <form id="bookingForm" novalidate>
        <div class="row">
          <div class="field half" id="firstField">
            <label for="first">First name <span class="required">*</span></label>
            <div class="input-wrap">
              <input id="first" class="btn" type="text" autocomplete="off">
              <span class="check">✓</span>
            </div>
          </div>
          <div class="field half" id="lastField">
            <label for="last">Last name <span class="required">*</span></label>
            <div class="input-wrap">
              <input id="last" class="btn" type="text" autocomplete="off">
              <span class="check">✓</span>
            </div>
          </div>
        </div>

        <div class="field full" id="emailField">
          <label for="email">Email Address <span class="required">*</span></label>
          <div class="input-wrap">
            <input id="email" class="btn" type="text" autocomplete="off">
            <span class="error-icon">!</span>
          </div>
          <div class="hint" id="emailHint" style="display:none">We'll send your confirmation details to <b id="emailValue"></b></div>
          <div class="error-text" id="emailError" style="display:none">Enter a valid email address</div>
        </div>

        <div class="field full">
          <label class="phone-label" for="phone">Phone (mobile number preferred) <span class="required">*</span></label>
          <div class="phone-row">
            <div class="country btn">
              <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.png" width="25" height="25" alt="US">
              <span class="chevron">⌄</span>
            </div>
            <input id="phone" class="phone-input btn" type="text" placeholder="+1 " autocomplete="off">
          </div>
        </div>
      </form>

      <div class="reservation">
        <h2>Reservation details</h2>
        <div class="spinner"></div>
      </div>

      <div class="legal">
        <p>By clicking "Next: Payment details" and completing a booking, you agree with the <a href="#" class="btn">terms and conditions</a> of Booking.com and the privacy policy of Musement.</p>
        <p>Please see our Privacy Statement to understand how we use and protect your personal information.<br>
        <a href="#" class="privacy btn">Privacy Statement</a></p>
      </div>
    </section>
    <aside class="side">
      <div class="skeleton"></div>
      <div class="skeleton"></div>
    </aside>
  </div>
</main>

<script>
  const first=document.getElementById('first'), last=document.getElementById('last');
  const email=document.getElementById('email'), phone=document.getElementById('phone');
  const firstField=document.getElementById('firstField'), lastField=document.getElementById('lastField');
  const emailField=document.getElementById('emailField'), hint=document.getElementById('emailHint');
  const error=document.getElementById('emailError'), emailValue=document.getElementById('emailValue');

  function markName(input, box){
    if(input.value.trim()) box.classList.add('valid'); else box.classList.remove('valid');
  }
  first.addEventListener('input',()=>markName(first,firstField));
  last.addEventListener('input',()=>markName(last,lastField));

  email.addEventListener('focus',()=>{
    if(email.value.trim() && !email.value.includes('@')){
      hint.style.display='block'; error.style.display='none'; emailField.classList.remove('email-error');
      emailValue.textContent=email.value;
    }
  });
  email.addEventListener('input',()=>{
    const v=email.value.trim();
    if(v && !v.includes('@')){
      hint.style.display='block'; error.style.display='none'; emailField.classList.remove('email-error'); emailValue.textContent=v;
    } else {
      hint.style.display='none';
    }
  });
  email.addEventListener('blur',()=>{
    const v=email.value.trim();
    if(v && !v.includes('@')){
      hint.style.display='none'; error.style.display='block'; emailField.classList.add('email-error');
    }
  });
  phone.addEventListener('focus',()=>{
    const v=email.value.trim();
    if(v && !v.includes('@')){
      hint.style.display='none'; error.style.display='block'; emailField.classList.add('email-error');
    }
  });
</script>
</body>
